func urlAccessDecodeOptionalInt64(object map[string]json.RawMessage, key, location string, diagnostics *diag.Diagnostics) int64 {
	raw, ok := object[key]
	if !ok || urlAccessJSONNull(raw) {
		return 0
	}
	var number json.Number
	if err := json.Unmarshal(raw, &number); err != nil {
		diagnostics.AddError("Malformed URL access result", location+" "+key+" was not an integer.")
		return 0
	}
	value, err := number.Int64()
	if err != nil {
		diagnostics.AddError("Malformed URL access result", location+" "+key+" was not an integer.")
		return 0
	}
	return value
}

// DecodeOptionalInt64WithDefault decodes an optional integer item field,
// substituting the reviewed default when the successful GET omits the key or
// returns null. This mirrors the encode path (PlannedOptionalInt64 sends the
// reviewed default when the practitioner omits the field), so state carries the
// reviewed default rather than 0 and a later update does not reuse a stale 0.
func urlAccessDecodeOptionalInt64WithDefault(object map[string]json.RawMessage, key, location string, defaultValue int64, diagnostics *diag.Diagnostics) int64 {
	raw, ok := object[key]
	if !ok || urlAccessJSONNull(raw) {
		return defaultValue
	}
	var number json.Number
	if err := json.Unmarshal(raw, &number); err != nil {
		diagnostics.AddError("Malformed URL access result", location+" "+key+" was not an integer.")
		return 0
	}
	value, err := number.Int64()
	if err != nil {
		diagnostics.AddError("Malformed URL access result", location+" "+key+" was not an integer.")
		return 0
	}
	return value
}

func urlAccessDecodeScalars(result client.WAFModuleResult) (urlAccessScalars, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	scalarsResult := urlAccessScalars{}

	statusRaw, ok := result.Configs["status"]
	if !ok || urlAccessJSONNull(statusRaw) {
		diagnostics.AddError("Malformed URL access result", "The successful API result did not contain a non-null status boolean.")
	} else {
		var statusValue bool
		if err := json.Unmarshal(statusRaw, &statusValue); err != nil {
			diagnostics.AddError("Malformed URL access result", "The successful API result contained an invalid status.")
		} else {
			scalarsResult.Status = statusValue
		}
	}
	return scalarsResult, diagnostics
}

func urlAccessDecodeRuleList(raw json.RawMessage) (urlAccessRuleListOwnedList, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(raw) == 0 {
		return urlAccessRuleListOwnedList{}, diagnostics
	}
	if urlAccessJSONNull(raw) {
		diagnostics.AddError("Malformed URL access result", "The successful API result contained null rule_list instead of an array.")
		return urlAccessRuleListOwnedList{}, diagnostics
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed URL access result", "The successful API result contained a non-array rule_list value.")
		return urlAccessRuleListOwnedList{}, diagnostics
	}
	if len(rawItems) > urlAccessRuleListMaxItems {
		diagnostics.AddError("Malformed URL access result", fmt.Sprintf("The successful API result contained more than %d rule_list items.", urlAccessRuleListMaxItems))
		return urlAccessRuleListOwnedList{}, diagnostics
	}

	items := make([]urlAccessRuleListWireItem, 0, len(rawItems))
	seen := make(map[int]struct{}, len(rawItems))
	knownKeys := map[string]struct{}{
		"action":   {},
		"idx":      {},
		"name":     {},
		"url":      {},
		"url_type": {},
	}
	for position, rawItem := range rawItems {
		location := fmt.Sprintf("rule_list item %d", position+1)
		var object map[string]json.RawMessage
		if err := json.Unmarshal(rawItem, &object); err != nil || object == nil {
			diagnostics.AddError("Malformed URL access result", location+" was not an object.")
			continue
		}
		unknown := make([]string, 0)
		for key := range object {
			if _, ok := knownKeys[key]; !ok {
				unknown = append(unknown, key)
			}
		}
		sort.Strings(unknown)
		if len(unknown) != 0 {
			diagnostics.AddError("Unknown URL access item field", location+" contained unsupported keys: "+strings.Join(unknown, ", ")+".")
			continue
		}
		index, ok := urlAccessDecodeIndex(object["idx"], location, "int", &diagnostics)
		if !ok {
			continue
		}
		if _, duplicate := seen[index]; duplicate {
			diagnostics.AddError("Malformed URL access result", fmt.Sprintf("%s used duplicate idx %d.", location, index))
			continue
		}
		seen[index] = struct{}{}
		item := urlAccessRuleListWireItem{Index: index}
		actionValue, ok := urlAccessDecodeRequiredString(object["action"], location+" action", &diagnostics)
		if !ok {
			continue
		}
		urlAccessValidateString(location, " action", actionValue, 0, 0, &diagnostics)
		if !urlAccessRuleListActionValid(actionValue) {
			diagnostics.AddError("Malformed URL access result", location+" action was not one of alert_deny, continue, deny_no_log, pass.")
		}
		item.Action = actionValue
		nameValue, ok := urlAccessDecodeRequiredString(object["name"], location+" name", &diagnostics)
		if !ok {
			continue
		}
		urlAccessValidateString(location, " name", nameValue, 0, 39, &diagnostics)
		item.Name = nameValue
		urlValue, ok := urlAccessDecodeRequiredString(object["url"], location+" url", &diagnostics)
		if !ok {
			continue
		}
		urlAccessValidateString(location, " url", urlValue, 0, 255, &diagnostics)
		item.URL = urlValue
		url_typeValue, ok := urlAccessDecodeRequiredString(object["url_type"], location+" url_type", &diagnostics)
		if !ok {
			continue
		}
		urlAccessValidateString(location, " url_type", url_typeValue, 0, 0, &diagnostics)
		if !urlAccessRuleListURLTypeValid(url_typeValue) {
			diagnostics.AddError("Malformed URL access result", location+" url_type was not one of regex, string.")
		}
		item.URLType = url_typeValue
		items = append(items, item)
	}
	if diagnostics.HasError() {
		return urlAccessRuleListOwnedList{}, diagnostics
	}
	sort.Slice(items, func(i, j int) bool { return items[i].Index < items[j].Index })
	return urlAccessRuleListOwnedList{Set: true, Items: items}, diagnostics
}

func urlAccessRuleListWrapperValue(owned urlAccessRuleListOwnedList, subItemOwnedMasks map[string][]bool) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if !owned.Set {
		return types.ObjectNull(urlAccessRuleListWrapperAttributeTypes), diagnostics
	}
	elements := make([]attr.Value, 0, len(owned.Items))
	for _, item := range owned.Items {
		objectValues := map[string]attr.Value{}
		objectValues["action"] = types.StringValue(item.Action)
		objectValues["name"] = types.StringValue(item.Name)
		objectValues["url"] = types.StringValue(item.URL)
		objectValues["url_type"] = types.StringValue(item.URLType)
		object, objectDiagnostics := types.ObjectValue(urlAccessRuleListItemAttributeTypes, objectValues)
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: urlAccessRuleListItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(urlAccessRuleListWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}
func urlAccessDecodeIndex(raw json.RawMessage, location string, idxKind string, diagnostics *diag.Diagnostics) (int, bool) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || urlAccessJSONNull(trimmed) {
		diagnostics.AddError("Malformed URL access result", location+" did not contain a non-null integer idx.")
		return 0, false
	}
	if trimmed[0] != '-' && (trimmed[0] < '0' || trimmed[0] > '9') {
		diagnostics.AddError("Malformed URL access result", location+" contained a non-integer idx.")
		return 0, false
	}
	var number json.Number
	if err := json.Unmarshal(trimmed, &number); err != nil {
		diagnostics.AddError("Malformed URL access result", location+" contained a non-integer idx.")
		return 0, false
	}
	value64, err := number.Int64()
	if err != nil || value64 <= 0 || int64(int(value64)) != value64 {
		diagnostics.AddError("Malformed URL access result", location+" contained an idx that was not a positive integer.")
		return 0, false
	}
	return int(value64), true
}
